<script setup>
import PageHeading from '../components/ui/PageHeading.vue'
import { ref, reactive, onMounted, onBeforeUnmount } from 'vue'
import { RouterLink } from 'vue-router'
import QRCode from 'qrcode'
import { applicationReviewSchema } from '@dacos/contracts'
import { useAuthStore } from '../stores/auth.js'
import { workerRegistrationUrl } from '../services/worker-registration.js'
const auth=useAuthStore(),rows=ref([]),status=ref('PENDING'),nextCursor=ref(null),detail=ref(null),workers=ref([]),zones=ref([]),error=ref(''),feedback=ref(''),loading=ref(true),busy=ref(false),qrOrigin=ref(''),qrUrl=ref(''),qrImage=ref(''),qrError=ref('')
const form=reactive({mode:'create',zoneId:'',workerId:'',note:'',duplicateAcknowledged:false})
let active=true,generation=0
async function load(append=false){loading.value=true;error.value='';try{const p=new URLSearchParams({status:status.value});if(append&&nextCursor.value)p.set('cursor',nextCursor.value);const result=await auth.request('/api/manage/worker-applications?'+p,undefined,'GET');if(!active)return;rows.value=append?[...rows.value,...result.data]:result.data;nextCursor.value=result.nextCursor}catch(e){error.value=e.message}finally{loading.value=false}}
async function select(id){const n=++generation;detail.value=null;error.value='';feedback.value='';try{const result=await auth.request(`/api/manage/worker-applications/${id}`,undefined,'GET');if(active&&n===generation){detail.value=result;Object.assign(form,{mode:'create',zoneId:zones.value[0]?.id??'',workerId:'',note:'',duplicateAcknowledged:false})}}catch(e){error.value=e.message}}
async function generateQr(){qrError.value='';qrImage.value='';qrUrl.value='';try{const url=workerRegistrationUrl(qrOrigin.value.trim());const image=await QRCode.toDataURL(url,{width:320,margin:4,errorCorrectionLevel:'M',color:{dark:'#071b2e',light:'#ffffff'}});if(!active)return;qrUrl.value=url;qrImage.value=image}catch(e){qrError.value=e.message}}
async function review(action){
  if(!detail.value||busy.value)return
  const payload=action==='reject'?{action,note:form.note}:{action,mode:form.mode,...(form.mode==='create'?{zoneId:form.zoneId}:{workerId:form.workerId}),note:form.note,duplicateAcknowledged:form.duplicateAcknowledged}
  const parsed=applicationReviewSchema.safeParse(payload)
  if(!parsed.success){error.value='Enter a review note (3–2000 characters) and select a zone or an existing worker.';return}
  if(!window.confirm(action==='reject'?'Reject this application? The decision and review note will be retained.':form.mode==='create'?'Approve and create an active worker? No account or device is created.':'Approve and link this application to the selected worker? Existing worker and private profile details will be retained.'))return
  busy.value=true;error.value=''
  try{const result=await auth.request(`/api/manage/worker-applications/${detail.value.application.id}/review`,parsed.data);const id=detail.value.application.id;await load();await select(id);feedback.value=`Application ${result.status.toLowerCase()}${result.workerId?` · Worker ${result.workerId}`:''}.`}
  catch(e){error.value=`${e.message} Your review note has been retained; refresh the application before retrying if it changed.`}
  finally{busy.value=false}
}
onMounted(async()=>{
  qrOrigin.value=window.location.origin
  await Promise.all([load(),generateQr(),(async()=>{try{const [w,z]=await Promise.all([auth.request('/api/manage/workers',undefined,'GET'),auth.request('/api/zones',undefined,'GET')]);if(active){workers.value=w.data.filter(w=>w.active);zones.value=z.data}}catch(e){error.value=e.message}})()])
})
onBeforeUnmount(()=>{active=false;generation++})
</script>
<template>
  <main class="connectivity-page applications-page"><nav><RouterLink to="/manage/workers">← Worker management</RouterLink><RouterLink to="/worker-register">Public registration form ↗</RouterLink></nav><p class="eyebrow">DACOS · PERSONNEL REVIEW</p><PageHeading title="Worker applications" eyebrow="DACOS / OPERATIONS"/><p>Public submissions remain pending until reviewed. Only authorized supervisors and administrators can access application details.</p>
    <details class="registration-qr"><summary>Registration QR code & public link</summary><div class="qr-grid"><div><label>Frontend origin<input v-model="qrOrigin" placeholder="https://your-approved-host" maxlength="300"></label><button @click="generateQr">Generate QR code</button><p>The QR contains only the public registration address. It is not a device pairing credential.</p><p>Localhost links work only on this computer. For phone testing, use an already configured, trusted HTTPS frontend address. Generating a QR does not deploy or expose the application.</p><p v-if="qrError" role="alert">{{qrError}}</p><a v-if="qrUrl" :href="qrUrl" class="qr-link">{{qrUrl}}</a></div><div v-if="qrImage"><img :src="qrImage" width="240" height="240" alt="QR code for the public DACOS worker application form"><a :href="qrImage" download="dacos-worker-registration.png">Download QR PNG</a></div></div></details>
    <p v-if="error" role="alert">{{error}}</p><p v-if="feedback" role="status">{{feedback}}</p>
    <div class="applications-grid"><section><h2>Application queue</h2><form @submit.prevent="detail=null;load()"><label>Review status<select v-model="status" :disabled="busy"><option>PENDING</option><option>APPROVED</option><option>REJECTED</option></select></label><button :disabled="loading||busy">Apply / refresh</button></form><p v-if="loading" role="status">Loading applications…</p><p v-else-if="!rows.length">No applications with this status.</p><article v-for="a in rows" :key="a.id" class="management-record"><h3>{{a.fullName}}</h3><p>{{a.jobTitle}} · {{a.site}} · {{a.shift}}</p><p>{{a.status}} · {{new Date(a.createdAt).toLocaleString()}}</p><button :disabled="busy" @click="select(a.id)">Review application</button></article><button v-if="nextCursor" :disabled="loading||busy" @click="load(true)">Load more</button></section>
      <section v-if="detail" class="application-detail"><h2>{{detail.application.fullName}}</h2><span class="badge">{{detail.application.status}}</span><dl><dt>Phone</dt><dd>{{detail.application.phone}}</dd><dt>Employee number</dt><dd>{{detail.application.employeeNumber||'Not provided'}}</dd><dt>Job title</dt><dd>{{detail.application.jobTitle}}</dd><dt>Work area</dt><dd>{{detail.application.workArea}}</dd><dt>Mine / site (applicant-provided)</dt><dd>{{detail.application.site}}</dd><dt>Shift</dt><dd>{{detail.application.shift}}</dd><dt>Emergency contact</dt><dd>{{detail.application.emergencyContact||'Not provided'}}</dd><dt>Privacy acknowledgement</dt><dd>{{detail.application.privacyVersion}} · {{new Date(detail.application.acknowledgedAt).toLocaleString()}}</dd></dl>
        <div class="duplicate-review"><h3>Duplicate review</h3><p v-if="!detail.duplicates.hasMatches">No potential matches found. This does not verify identity.</p><template v-else><p>Potential matches require human review; a shared phone or name does not prove the same identity.</p><p v-for="a in detail.duplicates.applications" :key="a.id">Application {{a.id}} · {{a.fullName}} · {{a.status}} · Match: {{a.reasons.join(', ')}} <span v-if="a.approvedWorkerId">· Worker {{a.approvedWorkerId}}</span></p><p v-for="w in detail.duplicates.workers" :key="w.workerId">Worker {{w.workerId}} · Match: {{w.reasons.join(', ')}}</p><p v-for="w in detail.duplicates.nameMatches" :key="w.id">Worker {{w.id}} · {{w.name}} · {{w.active?'Active':'Inactive'}} · Name match</p><p v-if="detail.duplicates.truncated">More than 50 matches. Investigate in Worker Management before approving.</p></template></div>
        <form v-if="detail.application.status==='PENDING'" @submit.prevent="review('approve')"><h3>Review decision</h3><label>Approval action<select v-model="form.mode" :disabled="busy"><option value="create">Create a new worker</option><option value="link">Link an existing active worker</option></select></label><label v-if="form.mode==='create'">Assigned administrative zone<select v-model="form.zoneId" :disabled="busy"><option value="">Select a zone</option><option v-for="z in zones" :key="z.id" :value="z.id">{{z.name}} · {{z.id}}</option></select></label><label v-else>Existing active worker<select v-model="form.workerId" :disabled="busy"><option value="">Select a worker</option><option v-for="w in workers" :key="w.id" :value="w.id">{{w.name}} · {{w.id}}</option></select></label><p v-if="form.mode==='link'">Linking preserves the worker's existing profile, zone and private contact details. The submitted details remain in this application.</p><p v-else>Approval creates an active personnel record with a generated ID. An assigned zone is not a tracked location.</p><label>Review note (required)<textarea v-model="form.note" required minlength="3" maxlength="2000" rows="4" :disabled="busy" placeholder="Explain the decision and any duplicate checks. Avoid unnecessary sensitive information."></textarea></label><label v-if="detail.duplicates.hasMatches" class="duplicate-check"><input v-model="form.duplicateAcknowledged" type="checkbox" :disabled="busy"> I reviewed the potential duplicates and documented the decision.</label><div class="review-actions"><button :disabled="busy||(detail.duplicates.hasMatches&&!form.duplicateAcknowledged)">{{busy?'Saving…':'Approve application'}}</button><button type="button" :disabled="busy" @click="review('reject')">Reject application</button></div></form>
        <div v-else><h3>Review outcome</h3><p>{{detail.application.reviewNote}}</p><p>Reviewed by {{detail.application.reviewedBy}} · {{new Date(detail.application.reviewedAt).toLocaleString()}}</p><RouterLink v-if="detail.application.approvedWorkerId" :to="`/workers/${detail.application.approvedWorkerId}`">Open worker →</RouterLink><p>Decisions are final for this application. Existing records and history are preserved.</p></div><h3>Audit history</h3><ol><li v-for="e in detail.events" :key="e.id">{{new Date(e.createdAt).toLocaleString()}} · {{e.action}} · {{e.actorId||'Public submission'}}</li></ol><button :disabled="busy" @click="select(detail.application.id)">Refresh application (clears draft note)</button>
      </section><section v-else><h2>Select an application</h2><p>Review details and potential duplicates before approving or rejecting. New workers receive a safe generated ID; login accounts are never created automatically.</p></section></div>
  </main>
</template>
<style scoped>
.applications-grid{display:grid;grid-template-columns:minmax(260px,.85fr) minmax(0,1.4fr);gap:24px}.applications-grid>section{min-width:0}.application-detail dd,.duplicate-review p,.qr-link{overflow-wrap:anywhere}.application-detail dt{color:#94a3b8;font-size:12px;margin-top:10px}.application-detail dd{margin:0 0 6px}.registration-qr{border:1px solid #334155;padding:18px;border-radius:8px;margin:24px 0}.registration-qr summary{cursor:pointer;font-weight:600}.qr-grid{display:grid;grid-template-columns:1fr 240px;gap:24px;margin-top:20px}.qr-grid img{background:white;border-radius:6px;max-width:100%;height:auto}.qr-grid a{display:block;margin-top:12px}.qr-grid p{font-size:12px;color:#94a3b8;margin-top:12px}.duplicate-review{padding:16px;background:#243339;border:1px solid #61735d;border-radius:7px;margin:24px 0}.duplicate-review p{font-size:12px}.duplicate-check{display:flex!important;gap:12px;align-items:flex-start;margin:18px 0}.duplicate-check input{width:18px!important;height:18px;margin:3px 0 0!important}.review-actions{display:flex;flex-wrap:wrap;gap:12px}.review-actions button:last-child{background:#552430;color:#fecdd3}.applications-page textarea{width:100%;background:#0c1626;color:#e2e8f0;border:1px solid #475569;border-radius:5px;padding:12px}.application-detail ol{font-size:12px;padding-left:18px}.application-detail h3{margin-top:22px}@media(max-width:800px){.applications-grid{grid-template-columns:1fr}.qr-grid{grid-template-columns:1fr}.qr-grid>div:last-child{max-width:240px}}
</style>
